from de import *
T=[]
def pronomen(ch,hard):
    t=DT('%s-deu-pronomen'%ch,ch,'Wortarten','Pronomen erkennen',seed=31+int(ch[2:]))
    t.th('basis','Pronomen','Stellvertreter stehen für ein Nomen: er, sie, es, wir. Begleiter stehen vor einem Nomen: mein, dein, sein, unser.')
    THEORY(t,"Anna spielt im Garten. Statt jedes Mal «Anna» zu sagen, sagst du «sie». Pronomen sind kleine Helfer in Sätzen.",SC('talk',t1='Anna lacht.',t2='Sie lacht!'),
      "Es gibt zwei Arten von Pronomen.",["Art","Das macht es","Beispiel"],[["{4|Stellvertreter}","Steht für ein Nomen","{4|Er} lacht. {4|Wir} spielen."],["{3|Begleiter}","Steht vor einem Nomen","{3|Mein} Hund. {3|Unser} Haus."]],
      "Die Farben zeigen, was zusammengehört.",
      [([("Anna","Nomen",0),("lacht","Verb",1),(".","",7),("Sie","Stellvertreter",4),("spielt","Verb",1)],"«Sie» steht für «Anna»."),([("Mein","Begleiter",3),("Hund","Nomen",0),("ist","Verb",1),("klein","Adjektiv",2)],"«Mein» begleitet das Nomen «Hund»."),([("Wir","Stellvertreter",4),("gehen","Verb",1),("in","",5),("unser","Begleiter",3),("Haus","Nomen",0)],"Beides in einem Satz.")],
      "So erkennst du ein Pronomen.",["Lies den Satz.","Steht das Wort für ein Nomen? Dann ist es ein Stellvertreter.","Steht das Wort vor einem Nomen und gehört dazu? Dann ist es ein Begleiter.","Probiere: Kannst du das Wort durch ein Nomen ersetzen?"],
      "Das ist wichtig.",[["Stellvertreter","ich, du, er, sie, es, wir, ihr, sie","Er lacht.",4],["Begleiter","mein, dein, sein, ihr, unser, euer","Mein Ball",3],["Nomen","Das Nomen bleibt gross.","der Hund",0]],
      fehler=[["Anna lacht. Anna spielt. Anna isst.","Anna lacht. Sie spielt. Sie isst.","Sag nicht immer das Nomen."],["Er Hund ist klein.","Sein Hund ist klein.","Vor einem Nomen steht ein Begleiter."],["Mein lacht.","Er lacht.","Allein steht ein Stellvertreter."]])
    if hard:more(t,'Die Pronomen im Überblick','Stellvertreter und Begleiter gibt es für jede Person. Merke dir die Reihen.',TBL(['Person','Stellvertreter','Begleiter'],[['ich','ich','mein'],['du','du','dein'],['er / es','er, es','sein'],['sie','sie','ihr'],['wir','wir','unser'],['ihr','ihr','euer']]))
    if not hard:
        S=[("Anna lacht. Sie spielt gern.","Sie",0),("Mein Hund ist klein.","Mein",1),("Tom ist müde. Er geht heim.","Er",0),("Dein Ball ist rot.","Dein",1),("Das Buch ist neu. Es liegt auf dem Tisch.","Es",0),("Unser Auto ist blau.","Unser",1),("Wir gehen in die Schule.","Wir",0),("Sein Bruder heisst Max.","Sein",1),("Ich male ein Bild.","Ich",0),("Euer Haus ist gross.","Euer",1),("Du bist mein Freund.","Du",0),("Wo ist dein Stift?","dein",1),("Ihr spielt im Garten.","Ihr",0),("Du bist mein Freund.","mein",1),("Lisa hat ihre Tasche vergessen.","ihre",1),("Die Kinder lachen. Sie rennen.","Sie",0),("Ich mag mein Fahrrad.","Ich",0),("Ich mag mein Fahrrad.","mein",1)]
        G=[("Tom ist müde. ___ geht heim.","Er",["Sein","Ihr","Mein"]),("Anna hat Hunger. ___ isst einen Apfel.","Sie",["Mein","Dein","Es"]),("Das Kind lacht. ___ spielt Ball.","Es",["Er","Mein","Dein"]),("___ Ball ist rot. (Der Ball gehört dir.)","Dein",["Du","Er","Wir"]),("Tom und ich spielen. ___ haben Spass.","Wir",["Dein","Unser","Er"]),("Das ist ___ Haus. (Das Haus gehört uns.)","unser",["wir","ihr","es"]),("Lena hat ___ Tasche vergessen.","ihre",["sie","er","wir"])]
        F=[("Ersetze «Der Hund»: ___ bellt laut.","Er"),("Ersetze «Die Katze»: ___ schläft.","Sie"),("Ersetze «Das Kind»: ___ lacht.","Es"),("Ersetze «Anna und ich»: ___ spielen.","Wir"),("Ersetze «Tom und Max»: ___ rennen.","Sie"),("Ersetze «Das Auto»: ___ ist schnell.","Es"),("Ersetze «Du und Lea»: ___ seid nett.","Ihr")]
    else:
        S=[("Die Lehrerin lobt den Schüler. Sie freut sich über seine Arbeit.","Sie",0),("Die Lehrerin lobt den Schüler. Sie freut sich über seine Arbeit.","seine",1),("Meine Schwester und ich fahren mit unserem Fahrrad zur Schule.","unserem",1),("Meine Schwester und ich fahren mit unserem Fahrrad zur Schule.","ich",0),("Der Nachbar hat einen Hund. Er bellt oft laut.","Er",0),("Haben Sie Ihren Schirm vergessen?","Ihren",1),("Die Kinder packen ihre Rucksäcke. Sie gehen los.","ihre",1),("Die Kinder packen ihre Rucksäcke. Sie gehen los.","Sie",0),("Wir besuchen morgen unsere Grosseltern.","Wir",0),("Wir besuchen morgen unsere Grosseltern.","unsere",1),("Das Mädchen hat ihr Heft verloren. Es sucht überall.","Es",0),("Das Mädchen hat ihr Heft verloren. Es sucht überall.","ihr",1),("Ihr habt euren Ball im Garten liegen lassen.","Ihr",0),("Ihr habt euren Ball im Garten liegen lassen.","euren",1),("Dein Bruder kennt meine Freundin gut.","meine",1),("Dein Bruder kennt meine Freundin gut.","Dein",1),("Die Katze putzt sich. Sie schnurrt dabei.","Sie",0),("Unser Lehrer erzählt eine Geschichte.","Unser",1),("Der Zug ist spät. Er kommt erst um acht.","Er",0),("Die Mutter ruft ihre Kinder.","ihre",1)]
        G=[("Der Lehrer lobt die Klasse. ___ ist zufrieden.","Er",["Sein","Ihr","Unser"]),("Die Kinder holen ___ Jacken.","ihre",["sie","wir","er"]),("Mein Vater sagt: «Ich mag ___ Arbeit.»","meine",["ich","mir","wir"]),("Das Baby schläft. ___ ist müde.","Es",["Sein","Ihr","Ihre"]),("Wo habt ihr ___ Schuhe gelassen?","eure",["ihr","uns","wir"]),("Lisa und Tim lachen. ___ Spiel macht Spass.","Ihr",["Sie","Es","Er"])]
        F=[("Ersetze «Die Lehrerin»: ___ erklärt die Aufgabe.","Sie"),("Ersetze «Das Mädchen»: ___ liest ein Buch.","Es"),("Ersetze «Der Nachbar und seine Frau»: ___ sind freundlich.","Sie"),("Ersetze «Max und ich»: ___ fahren Fahrrad.","Wir"),("Ersetze «Der Computer»: ___ ist neu.","Er"),("Ersetze «Die Bücher»: ___ liegen auf dem Tisch.","Sie")]
    P=["Stellvertreter","Begleiter"]
    cls(t,[((s,w),c) for s,w,c in S],P,lambda p:p[0]+"\nIst «%s» ein Stellvertreter oder ein Begleiter?"%p[1],hint=["Es steht für ein Nomen.","Es steht vor einem Nomen und gehört dazu."],why=lambda p,c:("«%s» steht für ein Nomen: Stellvertreter."%p[1]) if c==0 else ("«%s» begleitet ein Nomen: Begleiter."%p[1]),nc=12,ne=7,disp=lambda p:p[1],mq='Tippe alle an, die ein {c} sind.',mt=2,skip=lambda x:x.lower() in ('ihr','sie'))
    gaps(t,G,ne=3,q='Welches Wort passt?')
    forms(t,F,ne=4,hint='Das Pronomen am Satzanfang schreibt man gross.')
    for a,b,w in [("Er Hund ist klein.","Sein Hund ist klein.",""),("Anna lacht. Anna spielt.","Anna lacht. Sie spielt.",""),("Mein lacht.","Er lacht.","")][:0]:pass
    return t
T+= [lambda:pronomen('kl3',False),lambda:pronomen('kl4',True)]

def zeitformen(ch,hard):
    t=DT('%s-deu-zeitformen'%ch,ch,'Zeitformen','Die Zeitformen',seed=41+int(ch[2:]))
    t.th('basis','Zeitformen','Präsens: jetzt. Präteritum: früher, in Geschichten. Perfekt: früher, beim Erzählen. Perfekt = haben oder sein + Partizip.')
    THEORY(t,"Heute spielst du Fussball. Gestern hast du auch gespielt. Die Verben ändern sich, wenn sich die Zeit ändert.",SC('talk',t1='Ich spiele jetzt.',t2='Ich spielte gestern.'),
      "Es gibt drei Zeitformen. Sie sagen, wann etwas passiert.",["Zeitform","Wann?","Beispiel"],[["{2|Präsens}","jetzt","Ich lache."],["{3|Präteritum}","früher, in Geschichten","Ich lachte."],["{1|Perfekt}","früher, beim Erzählen","Ich habe gelacht."]],
      "Die Farben zeigen die Zeitform.",
      [([("Ich","",7),("spiele","Präsens",2),("Ball","",7)],"Jetzt: Präsens."),([("Ich","",7),("spielte","Präteritum",3),("Ball","",7)],"Früher: Präteritum."),([("Ich","",7),("habe","Perfekt",1),("Ball","",7),("gespielt","Perfekt",1)],"Früher: Perfekt mit «habe … gespielt».")],
      "So erkennst du die Zeitform.",["Suche das Verb im Satz.","Hat das Verb eine Endung wie -e, -st, -t und kein Hilfsverb? Dann ist es Präsens.","Hat es -te oder eine andere Form? Dann ist es Präteritum.","Gibt es «habe» oder «bin» und ein Wort mit ge-? Dann ist es Perfekt."],
      "Das ist wichtig.",[["Präsens","Es passiert jetzt.","Ich lese.",2],["Präteritum","Es ist vorbei.","Ich las.",3],["Perfekt","haben/sein + Partizip II","Ich habe gelesen.",1]],
      fehler=[["Gestern spiele ich Fussball.","Gestern spielte ich Fussball.","«Gestern» verlangt die Vergangenheit."],["Ich habe gespielte.","Ich habe gespielt.","Das Partizip von spielen endet auf -t."],["Jetzt lachte ich.","Jetzt lache ich.","«Jetzt» ist Gegenwart: Präsens."]])
    if hard:more(t,'Haben oder sein?','Das Perfekt bildest du mit «haben» oder «sein». Verben der Bewegung und der Veränderung brauchen meist «sein».',TBL(['Mit sein','Mit haben'],[['ich bin gegangen','ich habe gespielt'],['er ist gefahren','sie hat gelacht'],['wir sind gekommen','wir haben gegessen']]))
    if not hard:
        S=[("Ich spiele Fussball.",0),("Ich spielte Fussball.",1),("Ich habe Fussball gespielt.",2),("Anna lacht laut.",0),("Anna lachte laut.",1),("Anna hat laut gelacht.",2),("Wir gehen nach Hause.",0),("Wir gingen nach Hause.",1),("Wir sind nach Hause gegangen.",2),("Der Hund bellt.",0),("Der Hund bellte.",1),("Der Hund hat gebellt.",2),("Tom malt ein Bild.",0),("Tom malte ein Bild.",1),("Tom hat ein Bild gemalt.",2),("Sie singen ein Lied.",0),("Sie sangen ein Lied.",1),("Sie haben ein Lied gesungen.",2),("Mama kocht Suppe.",0),("Mama kochte Suppe.",1),("Mama hat Suppe gekocht.",2)]
        G=[("Gestern ___ ich Fussball.","spielte",["spiele","spielt","gespielt"]),("Jetzt ___ die Sonne.","scheint",["schien","geschienen","scheinte"]),("Wir haben ein Lied ___.","gesungen",["singen","sang","singt"]),("Er ___ gestern ein Bild.","malte",["malt","gemalt","malen"]),("Sie ___ jetzt ein Buch.","liest",["las","gelesen","lesen"]),("Gestern ___ der Hund laut.","bellte",["bellt","bellen","gebellt"]),("Ich habe einen Apfel ___.","gegessen",["essen","ass","esse"]),("Jeden Morgen ___ wir zur Schule.","gehen",["gegangen","gehe","geht"])]
        FX=[("Ich habe gespielte.","Ich habe gespielt."),("Gestern spiele ich.","Gestern spielte ich.","",["Gestern habe ich gespielt."]),("Er hat gelachte.","Er hat gelacht."),("Wir haben gesinget.","Wir haben gesungen."),("Sie sind gegangt.","Sie sind gegangen."),("Jetzt lachte ich.","Jetzt lache ich."),("Ich habe gemalte.","Ich habe gemalt."),("Gestern malt er.","Gestern malte er.","",["Gestern hat er gemalt."])]
    else:
        S=[("Die Kinder bauen eine Sandburg.",0),("Die Kinder bauten eine Sandburg.",1),("Die Kinder haben eine Sandburg gebaut.",2),("Der Zug fährt pünktlich ab.",0),("Der Zug fuhr pünktlich ab.",1),("Der Zug ist pünktlich abgefahren.",2),("Meine Schwester backt einen Kuchen.",0),("Meine Schwester backte einen Kuchen.",1),("Meine Schwester hat einen Kuchen gebacken.",2),("Der Lehrer erklärt die Aufgabe genau.",0),("Der Lehrer erklärte die Aufgabe genau.",1),("Der Lehrer hat die Aufgabe genau erklärt.",2),("Wir besuchen unsere Grosseltern.",0),("Wir besuchten unsere Grosseltern.",1),("Wir haben unsere Grosseltern besucht.",2),("Die Vögel fliegen nach Süden.",0),("Die Vögel flogen nach Süden.",1),("Die Vögel sind nach Süden geflogen.",2)]
        G=[("Gestern ___ der Zug zu spät.","kam",["kommt","gekommen","kamt"]),("Die Kinder haben den ganzen Tag ___.","gespielt",["spielen","spielten","spielt"]),("Letzte Woche ___ wir ins Kino.","gingen",["gehen","gegangen","geht"]),("Der Lehrer hat die Aufgabe ___.","erklärt",["erklärte","erklären","erklärst"]),("Sie ___ gerade ein Buch.","liest",["las","gelesen","lest"]),("Wir sind nach Bern ___.","gefahren",["fahren","fuhren","fährt"]),("Die Sonne ___ gestern den ganzen Tag.","schien",["scheint","geschienen","scheinte"]),("Er hat den Brief ___.","geschrieben",["schrieb","schreibt","schreiben"])]
        FX=[("Die Vögel sind geflogt.","Die Vögel sind geflogen."),("Er hat den Kuchen gebackt.","Er hat den Kuchen gebacken."),("Gestern kommt der Zug zu spät.","Gestern kam der Zug zu spät.","",["Gestern ist der Zug zu spät gekommen."]),("Wir haben gestern gespielen.","Wir haben gestern gespielt."),("Sie haben das Bild gemalen.","Sie haben das Bild gemalt."),("Der Zug ist abgefahrt.","Der Zug ist abgefahren."),("Jetzt besuchten wir Oma.","Jetzt besuchen wir Oma."),("Sie hat eine Geschichte erzählen.","Sie hat eine Geschichte erzählt.")]
    Z=['Präsens','Präteritum','Perfekt']
    cls(t,[(s,c) for s,c in S],Z,lambda p:"In welcher Zeitform steht der Satz?\n«%s»"%p if False else "%s\nIn welcher Zeitform steht der Satz?"%p,hint=["Es passiert jetzt.","Es ist vorbei und hat eine Form wie -te.","Es hat «habe» oder «bin» und ein Wort mit ge-."],why=lambda p,c:["Es passiert jetzt: Präsens.","Es ist vorbei, mit Präteritum-Form.","Es ist vorbei, mit «haben/sein» und Partizip: Perfekt."][c],nc=12,ne=8,multi=True,mt=3,mq='Tippe alle Sätze im {s} an.',disp=lambda p:p,sel=True,sq='Welcher Satz steht im {c}?',sqx='Welcher dieser Sätze steht im {c}?',jnt='Stimmt das? Der Satz steht im {c}.',jnp=True,ntyp=6)
    gaps(t,G,ne=5,q='Welche Verbform passt?')
    fixes(t,FX,ne=3,q='Korrigiere das Verb im Satz.',lvl=2)
    return t
T+= [lambda:zeitformen('kl3',False),lambda:zeitformen('kl4',True)]
